NativeSignal sys0_set_window_title(VM& vm, Thread& thread) {
    const uint32_t address = thread.stack.pop();
    const std::string title =
        address == 0
            ? std::string()
            : vm.memory().read_cstring(address, thread.base);
    vm.set_window_title(normalize_text_to_utf8(title));
    return NativeSignal::Continue;
}
